"""Temporary opt-in answer experiment; production files unchanged."""
from copy import deepcopy
import hashlib, inspect, json, sys, time
from pathlib import Path
ROOT=Path('C:/Users/34994/Desktop/seekra')
sys.path.insert(0,str(ROOT/'tests'))
import httpx
from test_documents import add_page
from test_research import deliver
from seekra.agent import execute_run
from seekra.answers import PROPERTIES,compile_answer,register_answer_tool
from seekra.cli import read_config
from seekra.models import DeepSeekModel
from seekra.operations import failure
from seekra.session import Session
from seekra.tools import ToolRegistry,default_registry
HERE=Path(__file__).parent

PROBE_DEFINITION={'type':'function','function':{'name':'submit_answer',
'description':'提交最终答案。你决定标题、结构、叙述顺序，按问题自然穿插解释、原文、建议和未知事项。blocks 中 markdown 是你的转述、解释或建议；source 节点由程序按 evidence 从1开始序号填入保存原文。逐字原文使用 source，不在 markdown 中自行拼写引文冒充程序核验；翻译属于模型转述。evidence 复制已交付正文 evidence_ref，quote 是最多400字符的原句定位线索，程序展示其原段和引用上下文，不能改写或翻译。每项 evidence 须有 source 节点使用，允许无需引用的明确未知答复。保留原文的对象、时点、条件和确定程度；建议依赖未确认机制时，在该建议旁明确前提，不宣称已可行。原文块会标注展示范围，不能把局部阅读描述成通读全文或证明整页不存在规定。失败按具体反馈修正引用、回查或撤回无依据主张；成功即交付，无需再重写。引用合法不认证语义。',
'parameters':{'type':'object','properties':{
'evidence':deepcopy(PROPERTIES['evidence']),
'blocks':{'type':'array','minItems':1,'maxItems':64,'items':{'anyOf':[
{'type':'object','properties':{'type':{'type':'string','enum':['markdown']},'text':{'type':'string'}},'required':['type','text'],'additionalProperties':False},
{'type':'object','properties':{'type':{'type':'string','enum':['source']},'evidence_index':{'type':'integer','minimum':1}},'required':['type','evidence_index'],'additionalProperties':False}
]}}},'required':['evidence','blocks'],'additionalProperties':False}}}

def compile_flexible(session,draft):
