        raise ValueError('需要 evidence 和 blocks')
    if len(json.dumps(draft,ensure_ascii=False))>16000:
        raise ValueError('终稿参数超过16000字符')
    if not isinstance(draft['evidence'],list):raise ValueError('evidence 需要列表')
    blocks=draft['blocks']
    if not isinstance(blocks,list) or not 1<=len(blocks)<=64:raise ValueError('blocks 需要1至64项')
    used=set()
    for i,block in enumerate(blocks,1):
        if not isinstance(block,dict):raise ValueError(f'blocks[{i}] 需要对象')
        if block.get('type')=='markdown':
            if set(block)!={'type','text'} or not isinstance(block['text'],str) or not block['text'].strip():
                raise ValueError(f'blocks[{i}] 需要非空 text')
        elif block.get('type')=='source':
            index=block.get('evidence_index')
