                raise ValueError(f'blocks[{i}] 需要实际存在的 evidence_index')
            used.add(index)
        else:raise ValueError(f'blocks[{i}] 的 type 需要 markdown 或 source')
    if not any(b['type']=='markdown' for b in blocks):raise ValueError('需要模型回答正文，不能只交付原文')
    if used!=set(range(1,len(draft['evidence'])+1)):raise ValueError('存在未使用的 evidence，补 source 节点或删除未用引用')
    # Temporary adapter reuses current source checks, not its fixed presentation.
    base=compile_answer(session,{'evidence':draft['evidence'],'judgments':[],'recommendations':[],
        'unknowns':[{'question':'实验内部编译占位','answer_impact':''}]})
    chunks=[];displayed=set()
    for block in blocks:
        if block['type']=='markdown':
            chunks.append(block['text'].strip());continue
        index=base['evidence_source_indices'][block['evidence_index']-1]
        row=base['source_quotes'][index-1]
        if index in displayed:
            chunks.append(f'（参见原文 {index}）');continue
        displayed.add(index)
        label={'paragraph':'原段','reference_context':'引用上下文','excerpt':'原段的局部片段'}[row['scope']]
        title=' / '.join(row['path']) or row['title']
        chunks.append(f'原文 {index} · {title} · 展示范围：{label}（不代表整页已核实）\n\n'+
            '> '+row['text'].strip().replace('\n','\n> ')+f'\n\n[来源]({row["url"]})')
    return {**base,'draft':deepcopy(draft),'answer':'\n\n'.join(chunks)+'\n',
        'experiment_format':'flexible_blocks_v1',
        'notice':'实验性自由结构；程序仅核验原文与引用范围，不认证转述、判断、建议或研究充分性。'}

def offline_checks():
    session=Session()
    page=add_page(session,'# Policy\n\nAfter 30 days offline, validate online.\n\nShared guest accounts are excluded.')
    draft={'evidence':[{'reference':page['evidence_ref'],'quote':'After 30 days offline, validate online.'}],
        'blocks':[{'type':'markdown','text':'## Direct conclusion\nUnknown reset mechanism.'},
        {'type':'source','evidence_index':1},{'type':'markdown','text':'## Next steps\nVerify reset behavior first.'}]}
    checks=[]
    try:compile_flexible(session,draft);raise AssertionError('unread reference accepted')
    except ValueError:checks.append('unread reference rejected')
    deliver(session);result=compile_flexible(session,draft)
    assert result['answer'].index('Direct conclusion')<result['answer'].index('原文 1')<result['answer'].index('Next steps')
    checks.append('model block ordering preserved, source taken from saved snapshot')
    for kind in ('quote','index','unused'):
        bad=deepcopy(draft)
        if kind=='quote':bad['evidence'][0]['quote']='Verification before day 30 is mandatory.'
        if kind=='index':bad['blocks'][1]['evidence_index']=2
        if kind=='unused':bad['blocks'].pop(1)
        try:compile_flexible(session,bad);raise AssertionError(f'{kind} accepted')
        except ValueError:checks.append(f'{kind} rejected')
    bad=deepcopy(draft);bad['blocks'][0]['text']='Every 28 days guarantees indefinite offline use.'
    assert compile_flexible(session,bad)['status']=='success'
    checks.append('unsupported semantic claim remains accepted: explicit known limitation')
    return checks

class CapturedModel(DeepSeekModel):
    def __init__(self,*args,**kwargs):
        super().__init__(*args,**kwargs);self.requests=[]
    def generate(self,messages,tools,**kwargs):
        if len(self.requests)>=6:raise RuntimeError('实验外部上限6次请求，非产品限制')
        self.requests.append({'messages':[{k:v for k,v in m.items() if k!='reasoning_content'} for m in messages],
            'tools':deepcopy(tools),'private_continuation_excluded':True})
        return super().generate(messages,tools,**kwargs)

def run_case(config,case,variant,repair=False):
    session=Session(secrets=(config['DEEPSEEK_API_KEY'],config['TAVILY_API_KEY']))
    page=add_page(session,case['source'],url='https://example.org/controlled/'+case['id'])
    base=default_registry(None,'not-used',session);registry=ToolRegistry()
    for definition in base.definitions:
        if definition['function']['name'] in {'read_document','read_section','find_in_documents','update_research'}:
            registry.register(definition,base.execute)
    submissions=[]
    if variant=='fixed':register_answer_tool(registry,session)
    else:
        def submit(call,pages,known):
            try:
                draft=json.loads(call['function']['arguments']);submissions.append(deepcopy(draft))
                if repair and len(submissions)==1:
                    raise ValueError('实验故障注入：第一个 evidence 的 quote 未匹配原文。请用 read_document 的 view=reference 回查该引用，复制实际原句后重新提交。原稿未交付。')
                result=compile_flexible(session,draft)
            except (ValueError,TypeError) as exc:
                result=failure('submit_answer','invalid_arguments',str(exc),**getattr(exc,'details',{}))
            return json.dumps(result,ensure_ascii=False)
        registry.register(PROBE_DEFINITION,submit,final_output='answer')
    question=(case['question']+'\n\n本题使用固定的虚构测试资料，快照已保存为 '+page['document_id']+
        '。请实际读取后按这份资料回答，不核实现实产品或其他网页。'+case['coverage']+
        '请单独调用 submit_answer 提交最终答案。保留无法确认的边界，不编造新规则。')
    started=time.monotonic()
    with httpx.Client(timeout=httpx.Timeout(90,connect=20)) as client:
        model=CapturedModel(client,config['DEEPSEEK_MODEL'],config['DEEPSEEK_API_KEY'],thinking=True)
        result=execute_run(question,model=model,registry=registry,session=session)
    record={'case':case['id'],'variant':variant,'repair_injection':repair,'question':question,
        'source':case['source'],'source_sha256':hashlib.sha256(case['source'].encode()).hexdigest(),
        'status':result.status,'answer':result.answer,'error':result.error,
        'seconds':round(time.monotonic()-started,2),'model_calls':len(model.requests),
        'requests':model.requests,'records':session.records,'usage':session.usage_totals(),
        'used_submission':any(r.get('answer_record_id') for r in session.records if r['kind']=='run_ended')}
    (HERE/f'{case["id"]}-{variant}{"-repair" if repair else ""}.json').write_text(
        json.dumps(record,ensure_ascii=False,indent=2),encoding='utf-8')
    print(json.dumps({k:record[k] for k in ('case','variant','repair_injection','status','model_calls','seconds','used_submission')},ensure_ascii=False),flush=True)
    return record

def main():
    checks=offline_checks();print(json.dumps({'offline_checks':checks},ensure_ascii=False),flush=True)
    if '--offline' in sys.argv:return
    config=read_config(ROOT/'.env')
    sources=json.loads((ROOT/'evals/claim-boundaries.json').read_text(encoding='utf-8'))['sources']
    cases=[
    {'id':'offline','source':'# Offline rules\n\n'+sources['offline']['text'],
     'question':'我已有 Pro 许可并下载过资源包，用共享访客账户连续离线45天是否可行？换成普通个人账户并每28天联网一次是否就能解决？请解释文档要求与建议。',
     'coverage':'快照包含本测试提供的相关规则全文，但不是对现实产品的调查。'},
    {'id':'operations','source':'# Deployment rules\n\n'+sources['operations']['text'],
     'question':'我是 Operator 成员，部署已启用但事先没有得到所有者批准，现已运行满7天。现在补批是否就能补救？访问列表检查和通知有什么时间要求？给出可执行建议并区分原文要求。',
     'coverage':'快照包含本测试提供的相关规则全文，但没有其他补充资料。'},
    {'id':'partial','source':'# Guide opening excerpt\n\n'+sources['partial']['text'],
     'question':'根据目前取得的片段，Windows 11 + Pro 能否保证连续离线45天？这个页面是否没有账户限制？请只回答现有材料支持的部分并说明缺口。',
     'coverage':'保存的内容只是页面开头片段；Offline requirements 未读完，Limitations 尚未读取，本次没有后续正文。'}]
    rows=[]
    for i,case in enumerate(cases):
        for variant in (('fixed','flexible') if i%2==0 else ('flexible','fixed')):
            rows.append(run_case(config,case,variant))
    rows.append(run_case(config,cases[0],'flexible',repair=True))
    report={'date':'2026-10-07','question':'Free-order Markdown and verified source blocks as an opt-in answer candidate',
        'model':config['DEEPSEEK_MODEL'],'thinking':True,'reasoning_effort':'high','max_output_tokens':8192,
        'production_modified':False,'default_changed':False,'live_tavily_calls':0,
        'limits':'One sample per case and format; fixed fictional sources. Real model with production execute_run and local reading. No discovery, pressure, or recovery quality comparison. Repair run injects one synthetic validation failure. Tool schema and formatting instructions change together, not a pure rendering-only comparison.',
        'offline_checks':checks,'candidate_definition':PROBE_DEFINITION,
        'candidate_compiler':inspect.getsource(compile_flexible),'rows':rows}
    (HERE/'report.json').write_text(json.dumps(report,ensure_ascii=False,indent=2),encoding='utf-8')
    print(json.dumps({'finished':True,'model_calls':sum(r['model_calls'] for r in rows)},ensure_ascii=False),flush=True)

if __name__=='__main__':main()

